# Documentation

Taskflow keeps three kinds of document under `docs/`. They do not carry equal weight.

| Folder | What it is | Weight |
|---|---|---|
| `docs/adr/` | Architecture Decision Records: numbered, dated, reviewed. | **Authoritative.** |
| `docs/product/` | Product notes written before or alongside a feature: intent, examples, wording. | Context only. |
| `docs/support/` | Runbooks and support macros: what people observed. | Describes behaviour, never specifies it. |

## Precedence

1. An ADR is the specification for every question it addresses. The highest-numbered ADR that addresses a question is the one that applies; a later ADR supersedes an earlier one only where it says so.
2. Where a product note and an ADR disagree, the ADR wins. A product note that predates an ADR on the same subject is kept for history, not as a second opinion.
3. Support notes record what was seen at the time. They are never evidence of intended behaviour.
4. Code comments, `TODO`s and function names are not documentation. They are frequently stale.
5. Where no document speaks, the current behaviour of the code is authoritative, and a new feature follows the conventions of its sibling features (same error classes, same guards, same events).

"use client";

/**
 * Ctrl+K search overlay; advanced syntax requires `advanced_search`.
 *
 * Must call (do not reimplement): isEnabled
 */
import { useEffect, useState } from "react";
import { Dialog } from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Spinner } from "@/components/ui/spinner";
import { ANONYMOUS_FLAG_CONTEXT } from "@/hooks/flag-context";
import { useDebouncedValue } from "@/hooks/use-debounced-value";
import { isEnabled } from "@/lib/feature-flags";
import type { SearchQueryInput } from "@/schemas/search";
import type { SearchHit } from "@/server/services/search-service";
import type { ActionResult } from "@/types/api";
import type { OrgId } from "@/types/common";
import type { FeatureFlagSnapshot } from "@/types/feature-flag";
import type { ReactElement } from "react";
import { describeQuery, parseSearchQuery } from "./query-syntax";
import { SearchResults } from "./search-results";

export type SearchDialogProps = {
  open: boolean;
  orgId: OrgId;
  flags: FeatureFlagSnapshot;
  onClose: () => void;
  onSearch: (input: SearchQueryInput) => Promise<ActionResult<SearchHit[]>>;
};

const SEARCH_PAGE_SIZE = 20;

export function SearchDialog(props: SearchDialogProps): ReactElement | null {
  const { open, orgId, flags, onClose, onSearch } = props;

  const [raw, setRaw] = useState("");
  // Results are stored together with the query that produced them, so
  // "still searching" is derived rather than a second piece of state that
  // could disagree with the first.
  const [results, setResults] = useState<{
    query: string;
    hits: readonly SearchHit[];
  }>({ query: "", hits: [] });

  const debounced = useDebouncedValue(raw);
  const advanced =
    flags.advanced_search === true ||
    isEnabled("advanced_search", { ...ANONYMOUS_FLAG_CONTEXT, orgId });
  const parsed = parseSearchQuery(debounced, advanced);

  const query = parsed.text;
  const pending = query.length > 0 && results.query !== query;

  useEffect(() => {
    if (!open || query.length === 0) return;

    let cancelled = false;

    void onSearch({
      orgId,
      q: query,
      kinds: [...parsed.kinds],
      ...(parsed.projectId !== null ? { projectId: parsed.projectId } : {}),
      limit: SEARCH_PAGE_SIZE,
    }).then((result) => {
      if (cancelled) return;
      setResults({ query, hits: result.ok ? result.data : [] });
    });

    return () => {
      cancelled = true;
    };
    // `parsed` is derived from the debounced string; depending on its parts
    // keeps the effect from re-firing on every keystroke.
  }, [open, orgId, onSearch, query, parsed.kinds, parsed.projectId]);

  if (!open) return null;

  return (
    <Dialog
      open={open}
      title="Search"
      description={
        advanced
          ? "Use kind:issue or project:<id> to narrow the search."
          : undefined
      }
      onClose={onClose}
    >
      <Input
        name="q"
        type="search"
        value={raw}
        placeholder={advanced ? "kind:comment deploy failed" : "Search…"}
        onChange={setRaw}
      />

      {advanced && debounced.length > 0 ? (
        <p className="mt-1 text-xs text-neutral-500">{describeQuery(parsed)}</p>
      ) : null}

      <div className="mt-3">
        {pending ? (
          <Spinner size="sm" label="Searching" />
        ) : (
          <SearchResults
            hits={results.query === query ? results.hits : []}
            query={query}
            onSelect={() => onClose()}
          />
        )}
      </div>
    </Dialog>
  );
}
/**
 * JSON search endpoint used by the command palette.
 *
 * Owner D. The palette hits this route rather than the Server Action because it
 * fires on every keystroke and wants a plain cancellable fetch. Like
 * `searchAction` it asks for every kind and leaves the plan gating to the
 * service, so neither entry point can be the lenient one.
 *
 * Must call (do not reimplement): can, isEnabled
 */

import { errorResponse, failure } from "@/app/api/_lib/responses";
import { getActor } from "@/lib/actor";
import { isEnabled } from "@/lib/feature-flags";
import { can } from "@/lib/permissions";
import { searchQuerySchema } from "@/schemas/search";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { getOrganizationSummary } from "@/server/services/organization-service";
import { search } from "@/server/services/search-service";

export const dynamic = "force-dynamic";

const PALETTE_LIMIT = 10;

export async function GET(request: Request): Promise<Response> {
  try {
    const url = new URL(request.url);
    const orgSlug = url.searchParams.get("orgSlug");
    const q = url.searchParams.get("q");

    if (orgSlug === null || q === null) {
